namespace optiling {
const uint32_t BLOCK_DIM = 8;

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    MatmulMishMishCustomTilingData tiling;

    const gert::Shape* x_shape = context->GetInputShape(0);     // [m, k]
    const gert::Shape* wt_shape = context->GetInputShape(1);    // [k, n]
    if (x_shape->GetDimNum() != 2 || wt_shape->GetDimNum() != 2) {
        return ge::GRAPH_FAILED;
    }
    uint32_t m = static_cast<uint32_t>(x_shape->GetDim(0));
    uint32_t k = static_cast<uint32_t>(x_shape->GetDim(1));
    uint32_t k2 = static_cast<uint32_t>(wt_shape->GetDim(0));
    uint32_t n = static_cast<uint32_t>(wt_shape->GetDim(1));
    if (k != k2) {
        return ge::GRAPH_FAILED;
    }

    context->SetBlockDim(BLOCK_DIM);
    tiling.set_m(m);
    tiling.set_k(k);
    tiling.set_n(n);
    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t* currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
}

namespace ge {
static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    const gert::Shape* x_shape = context->GetInputShape(0);   // [m, k]
    const gert::Shape* wt_shape = context->GetInputShape(1);  // [k, n]
    if (x_shape->GetDimNum() != 2 || wt_shape->GetDimNum() != 2) {
        return GRAPH_FAILED;
    }
    uint64_t m = x_shape->GetDim(0);
    uint64_t n = wt_shape->GetDim(1);
    gert::Shape* y_shape = context->GetOutputShape(0);
    y_shape->SetDimNum(2);
    y_shape->SetDim(0, m);
    y_shape->SetDim(1, n);
    return GRAPH_SUCCESS;
}

